  (0xbda4e0, 8, 32); (0xbda500, 8, 32); (0xbda520, 1, 32)
].

(* [comment removed for export] *)
Definition gd_okb (g : gdesc) : bool :=
  (gd_beg g mod 32 =? 0) && (0 <? gd_size g) && (gd_size g <? gd_szrz g) && (gd_szrz g mod 32 =? 0)
  && (0x10000 <=? gd_beg g) && (gd_beg g + gd_szrz g <=? GD_IMG_END).

Lemma GDESC_ok : forallb gd_okb GDESC = true.
Proof. vm_compute. reflexivity. Qed.

Lemma GDESC_length : length GDESC = 11835%nat.
Proof. vm_compute. reflexivity. Qed.

Lemma GDESC_bounds : forall g, In g GDESC ->
  gd_beg g mod 32 = 0 /\ 0 < gd_size g < gd_szrz g /\ gd_szrz g mod 32 = 0 /\ 0x10000 <= gd_beg g /\ gd_beg g + gd_szrz g <= GD_IMG_END.
Proof.
  intros g Hg. pose proof (proj1 (forallb_forall _ _) GDESC_ok g Hg) as H. unfold gd_okb in H.
  repeat (apply andb_prop in H; destruct H as [H ?]).
  repeat match goal with
         | X : (_ =? _) = true |- _ => apply Z.eqb_eq in X
         | X : (_ <? _) = true |- _ => apply Z.ltb_lt in X
         | X : (_ <=? _) = true |- _ => apply Z.leb_le in X
         end.
  lia.
Qed.

(* [comment removed for export] *)
Definition gd_eqb (g h : gdesc) : bool := (gd_beg g =? gd_beg h) && (gd_size g =? gd_size h) && (gd_szrz g =? gd_szrz h).
Definition gd_memb (g : gdesc) : bool := existsb (gd_eqb g) GDESC.

Lemma gd_memb_In : forall g, gd_memb g = true -> In g GDESC.
Proof.
  intros [[b s] z] H. unfold gd_memb in H. apply existsb_exists in H as ([[b' s'] z'] & Hin & E).
  unfold gd_eqb, gd_beg, gd_size, gd_szrz in E. cbn [fst snd] in E.
  apply andb_prop in E as [E E3]. apply andb_prop in E as [E1 E2].
  apply Z.eqb_eq in E1, E2, E3. subst. exact Hin.
Qed.

(* [comment removed for export] *)
Definition gd_find (a : Z) : option gdesc := find (fun g => (gd_beg g <=? a) && (a <? gd_beg g + gd_size g)) GDESC.

Lemma gd_find_In : forall a g, gd_find a = Some g -> In g GDESC /\ gd_beg g <= a < gd_beg g + gd_size g.
Proof.
  intros a g H. unfold gd_find in H. apply find_some in H as [Hin E]. apply andb_prop in E as [E1 E2].
  apply Z.leb_le in E1. apply Z.ltb_lt in E2. split; [exact Hin | lia].
Qed.
